/// Opaque source symbol. K comparisons use canonical signed-decimal names.
/// Other spellings belong to the typed host API, outside that common domain.
pub type Name = String;
pub type Environment = BTreeMap<Name, Value>;
pub type ExprRef = Arc<Expr>;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Tree {
    Leaf(u128),
    Branch(Arc<Tree>, Arc<Tree>),
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Value {
    UInt(u128),
    Bool(bool),
    List(Vec<u128>),
    Tree(Tree),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Type {
    UInt,
    Bool,
    List,
    Tree,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Expr {
    Literal(Value),
    Var(Name),
    Let(Name, ExprRef, ExprRef),
    Binary(BinaryOp, ExprRef, ExprRef),
    Unary(UnaryOp, ExprRef),
    If(ExprRef, ExprRef, ExprRef),
    Call(Name, Vec<ExprRef>),
    Match(ExprRef, Vec<Arm>),
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Parameter {
    pub name: Name,
    pub ty: Type,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Function {
    pub name: Name,
    pub parameters: Vec<Parameter>,
    pub return_type: Type,
    pub body: ExprRef,
}

/// Function order is significant: lookup takes the first matching name.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Program {
    pub functions: Vec<Function>,
    pub entry: ExprRef,
}

pub const FORMAT: &str = "moriarty-sherlock-scalar-source-projection/1";

/// Maintainer preparation budget: the maximum number of source occurrences a
/// single report (summed across its actions) will materialize. Preparation
/// expands the validated Core expression DAG once per traversed edge with no
/// sharing, so a DAG of linear size can demand exponentially many occurrences
/// (and matching generated AST nodes) even within the existing depth-64 and
/// 8192-expression Core bounds. This ceiling is a representation-preparation
/// limit only: it is not a Core schema rule, resource/circuit cost, or any
/// change to the compiler's supported subset. Exhaustion is per-site
/// `Unsupported` metadata, never a compiler refusal.
pub const MAX_PROJECTION_OCCURRENCES: usize = crate::MAX_EXPRESSIONS + crate::MAX_STATEMENTS;

pub const LANGUAGE: &str = "moriarty/1";
pub const SEMANTICS: &str = "moriarty-core/1";
pub const MAX_EXPRESSIONS: usize = 8192;
pub const MAX_STATEMENTS: usize = 1024;
pub const MAX_DECLARATIONS: usize = 256;
pub const MAX_TRACE_CELLS: usize = 65_536;

/// Report every action without changing the real compiler's supported subset.
pub fn source_projection_report(program: &Program) -> SourceProjectionReport {
    let validation = crate::validate(program);
    let mut remaining = MAX_PROJECTION_OCCURRENCES;
    let actions = program.actions.iter().enumerate().map(|(index, action)| {
        let result = match &validation {
            Ok(()) => prepare_validated_action(program, index, &mut remaining),
            Err(error) => Err(diagnostic(index, None, None, "core-validation", &error.code)),
        };
        match result {
            Ok(map) => ActionProjection::Prepared { report: map.report },
            Err(diagnostic) => ActionProjection::Unsupported {
                action_index: index, action: action.name.clone(), diagnostic,
            },
        }
    }).collect();
    SourceProjectionReport {
        format: FORMAT.into(), source_language: program.language.clone(),
        source_semantics: program.semantics.clone(), agreement: program.name.clone(),
        reference_profile: PROFILE.into(), qualification: "source-static-scalar-projection-only".into(),
        source_function_support: false, source_branch_support: false,
        source_recursion_support: false, source_data_support: false,
        evaluation_performed: false, source_expression_count: program.expressions.len(),
        source_action_count: program.actions.len(), source_state_count: program.states.len(),
        source_asset_count: program.assets.len(),
        coverage: "direct scalar nodes; stateless actions; ordered lets and one final emit value; first unsupported site per action; no effects execution or unvisited-site mapping".into(),
        actions,
    }
}

/// Compile a typed scalar body with dynamic ordered parameters. The generated
/// function is a representation wrapper; it is not a source function feature.
pub fn prepare_scalar_action(program: &Program, action_index: usize)
    -> Result<ScalarActionMap, ProjectionDiagnostic>
{
    crate::validate(program).map_err(|error|
        diagnostic(action_index, None, None, "core-validation", &error.code))?;
    let mut remaining = MAX_PROJECTION_OCCURRENCES;
    prepare_validated_action(program, action_index, &mut remaining)
}

fn prepare_validated_action(program: &Program, index: usize, remaining: &mut usize)
    -> Result<ScalarActionMap, ProjectionDiagnostic>
{
    let action = program.actions.get(index).ok_or_else(||
        diagnostic(index, None, None, "action-index", "no-such-action"))?;
    if program.language != crate::LANGUAGE || program.semantics != crate::SEMANTICS {
        return Err(diagnostic(index, None, None, "source-profile", "unsupported-projection"));
    }
    if !program.states.is_empty() || !program.assets.is_empty() {
        return Err(diagnostic(index, None, None, "state-or-asset-declaration", "unsupported-projection"));
    }
    let mut lets = Vec::new();
    let mut emit = None;
    for (statement_index, statement) in action.statements.iter().enumerate() {
        match statement {
            Statement::Let { name, value } if emit.is_none() => lets.push(LetSite {
                statement_index, name: name.clone(), expression: *value,
            }),
            Statement::Emit { name, value } if statement_index + 1 == action.statements.len() => {
                emit = Some(EmitSite { statement_index, name: name.clone(), expression: *value,
                    role: "value-projection; ordered emit effect remains in Core".into() });
            }
            other => return Err(diagnostic(index, Some(statement_index), None,
                statement_kind(other), "unsupported-projection")),
        }
    }
    let emit = emit.ok_or_else(|| diagnostic(index, None, None,
        "final-emit", "missing-projection-observation"))?;

let mut types: std::collections::BTreeMap<String, crate::Type> = action.inputs.iter()
    .map(|input| (input.name.clone(), input.ty)).collect();
let mut occurrences = Vec::new();
let mut mapped_lets = Vec::new();
let mut path = Vec::new();
for site in &lets {
    charge(remaining, index, Some(site.statement_index), None)?;
    occurrences.push(SourceOccurrence { action_index: index, statement_index: site.statement_index,
        expression: None, body_path: path.clone(), node_kind: "let".into(), source_expression: None });
    let mut value_path = path.clone(); value_path.push(0);
    let value = map_expression(program, index, site.statement_index, site.expression,
        value_path, &mut occurrences, remaining)?;
    let ty = crate::runtime::expr_type(program, site.expression, &types, 0)
        .map_err(|error| diagnostic(index, Some(site.statement_index), Some(site.expression),
            "expression-type", &error.code))?;
    types.insert(site.name.clone(), ty);
    mapped_lets.push((site.name.clone(), value));
    path.push(1);
}
let mut body = map_expression(program, index, emit.statement_index, emit.expression,
    path, &mut occurrences, remaining)?;
let return_type = crate::runtime::expr_type(program, emit.expression, &types, 0)
    .map_err(|error| diagnostic(index, Some(emit.statement_index), Some(emit.expression),
        "expression-type", &error.code))?;
for (name, value) in mapped_lets.into_iter().rev() {
    body = Arc::new(Expr::Let(name, value, body));
}
let inputs: Vec<_> = action.inputs.iter().enumerate().map(|(index, input)|
    InputSite { index, name: input.name.clone(), ty: input.ty }).collect();
let function = Function { name: action.name.clone(),
    parameters: inputs.iter().map(|input| Parameter {
        name: input.name.clone(), ty: scalar_type(input.ty),
    }).collect(), return_type: scalar_type(return_type), body };
let report = ScalarActionReport { action_index: index, action: action.name.clone(), inputs,
    lets, emit, occurrences, return_type, generated_function_name: function.name.clone(),
    symbol_domain: "typed-host-symbols; no K numeric-name correspondence claimed".into() };
Ok(ScalarActionMap { function, report })

fn map_expression(program: &Program, action: usize, statement: usize, id: ExprId,
    path: Vec<usize>, occurrences: &mut Vec<SourceOccurrence>, remaining: &mut usize)
    -> Result<ExprRef, ProjectionDiagnostic>
{
    let source = program.expressions.get(usize::from(id)).ok_or_else(||
        diagnostic(action, Some(statement), Some(id), "expression-index", "no-such-expression"))?;
    let kind = match source {
        CoreExpr::Literal { .. } => "literal", CoreExpr::Name { .. } => "name",
        CoreExpr::Binary { .. } => "binary", CoreExpr::Not { .. } => "not",
        CoreExpr::LiabilityPresent { .. } => "liability-present",
        CoreExpr::LiabilityAmount { .. } => "liability-amount",
    };
    charge(remaining, action, Some(statement), Some(id))?;
    occurrences.push(SourceOccurrence { action_index: action, statement_index: statement,
        expression: Some(id), body_path: path.clone(), node_kind: kind.into(),
        source_expression: Some(source.clone()) });
    let child = |id, position, occurrences: &mut Vec<SourceOccurrence>, remaining: &mut usize| {
        let mut child_path = path.clone(); child_path.push(position);
        map_expression(program, action, statement, id, child_path, occurrences, remaining)
    };
    let mapped = match source {
        CoreExpr::Literal { value } => Expr::Literal(match value {
            crate::Value::UInt(value) => Value::UInt(value.0),
            crate::Value::Bool(value) => Value::Bool(*value),
        }),
        CoreExpr::Name { name } => Expr::Var(name.clone()),
        CoreExpr::Not { value } => Expr::Unary(UnaryOp::Not, child(*value, 0, occurrences, remaining)?),
        CoreExpr::Binary { op, lhs, rhs } => {
            let op = match op {
                CoreOp::Add => BinaryOp::Add, CoreOp::Sub => BinaryOp::Sub,
                CoreOp::Mul => BinaryOp::Mul, CoreOp::Eq => BinaryOp::Eq,
                CoreOp::Lt => BinaryOp::Lt,
                other => return Err(diagnostic(action, Some(statement), Some(id),
                    &format!("binary-{other:?}"), "unsupported-projection")),
            };
            let left = child(*lhs, 0, occurrences, remaining)?;
            let right = child(*rhs, 1, occurrences, remaining)?;
            Expr::Binary(op, left, right)
        }
        CoreExpr::LiabilityPresent { .. } | CoreExpr::LiabilityAmount { .. } =>
            return Err(diagnostic(action, Some(statement), Some(id), kind, "unsupported-projection")),
    };
    Ok(Arc::new(mapped))
}

pub const QUALIFICATION: &str =
    "bounded-host-observation; stateless scalar Core/1 projection; operation, slot and nesting counts only";

/// Caller-stated finite extents. There is deliberately no `Default`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct HostObservationBounds {
    /// Borrowed source shape, checked before Core validation walks it.
    pub max_source_actions: usize,
    pub max_source_expressions: usize,
    /// Statements summed over every action; Core validation types each one.
    pub max_source_statements: usize,
    pub max_scalar_arguments: usize,
    /// Unshared occurrences, checked before the adapter's own fixed budget.
    pub max_projection_occurrences: usize,
    /// Generated body nesting. This bounds derived Drop/Clone/PartialEq/Debug
    /// recursion over the generated AST; its native stack use is unmeasured.
    pub max_ast_nesting: usize,
    /// The A frame cap `L`, passed unchanged to `Machine::new`. Reaching it is
    /// the existing A `Rejected(4)` outcome, never a host refusal.
    pub stack_limit: usize,
    /// Retained step records. Admission requires `initial_fuel + 1 <= max_step_records`.
    pub max_step_records: usize,
    /// Ceiling on [`HostExtent::peak_slot_bound`].
    pub max_retained_slots: u128,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum HostMeasure {
    SourceActions,
    SourceExpressions,
    SourceStatements,
    ScalarArguments,
    ProjectionOccurrences,
    AstNesting,
    StepRecords,
    RetainedSlots,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum HostObservationRefusal {
    /// `required: None` means the checked count overflowed `u128`.
    Exceeded { measure: HostMeasure, required: Option<u128>, bound: u128 },
    /// The actual Core validation error, unchanged.
    CoreValidation(crate::Error),
    NoSuchAction { action_index: usize, action_count: usize },
    /// Lists and trees are outside the scalar domain. Only the discriminant is read.
    NonScalarArgument { index: usize },
    /// The actual adapter diagnostic, unchanged; it is not a compiler refusal.
    Projection(ProjectionDiagnostic),
    /// Actual adapter output fell outside this consumer's admitted shape.
    PreparationContract { detail: &'static str },
    /// Defensive: admitted fuel guarantees publication within the admitted records.
    UnpublishedOutcome,
}

/// Admission counts for one observation. The slot unit is one scalar value,
/// environment entry, parameter or expression reference. Environment keys are
/// Core identifiers of at most 64 bytes; no byte total is claimed. The shared
/// generated program and report are bounded by occurrences and nesting instead.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct HostExtent {
    pub bounds: HostObservationBounds,
    /// Lets plus unshared expression nodes over every let and emit value.
    pub projected_occurrences: u128,
    pub ast_nesting_bound: u128,
    /// Measured iteratively on the actual generated body.
    pub observed_ast_nesting: usize,
    /// `initial_fuel + 1`: one per charged step plus one free publication.
    pub step_record_bound: u128,
    /// `min(stack_limit, initial_fuel)`: a step pushes at most one frame.
    pub frame_bound: u128,
    /// Arity plus lets: the distinct names any machine environment can hold.
    pub environment_entry_bound: u128,
    /// `(2 * initial_fuel + 6) * (frame_bound + 3) * (entries + 2 * arity + 1)`.
    pub peak_slot_bound: u128,
    pub argument_types_match_inputs: bool,
}

/// The actual adapter report, generated program and machine records.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BoundedSourceObservation {
    pub report: ScalarActionReport,
    /// The same allocation every retained snapshot references.
    pub program: Arc<Program>,
    pub initial: Snapshot,
    pub records: Vec<StepRecord>,
    pub terminal: Snapshot,
    /// Actual post-publication step probe; separate from the terminal snapshot.
    pub terminal_has_next: bool,
    pub extent: HostExtent,
    pub qualification: &'static str,
}

pub fn observe_scalar_action(program: &crate::Program, action_index: usize, arguments: &[Value],
    initial_fuel: u128, bounds: HostObservationBounds)
    -> Result<BoundedSourceObservation, HostObservationRefusal>
{
    within(HostMeasure::SourceActions, Some(count(program.actions.len())),
        count(bounds.max_source_actions))?;
    within(HostMeasure::SourceExpressions, Some(count(program.expressions.len())),
        count(bounds.max_source_expressions))?;
    let statements = program.actions.iter()
        .try_fold(0u128, |sum, action| sum.checked_add(count(action.statements.len())));
    within(HostMeasure::SourceStatements, statements, count(bounds.max_source_statements))?;
    within(HostMeasure::ScalarArguments, Some(count(arguments.len())),
        count(bounds.max_scalar_arguments))?;
    if let Some(index) = arguments.iter()
        .position(|value| !matches!(value, Value::UInt(_) | Value::Bool(_)))
    {
        return Err(HostObservationRefusal::NonScalarArgument { index });
    }
    let action = program.actions.get(action_index).ok_or(HostObservationRefusal::NoSuchAction {
        action_index, action_count: program.actions.len(),
    })?;
    crate::validate(program).map_err(HostObservationRefusal::CoreValidation)?;

    // Validation orders every child before its parent, so one forward pass gives
    // unshared tree sizes and node depths without recursion. Saturated sizes
    // exceed every usize bound and are refused below.
    let mut sizes: Vec<u128> = Vec::with_capacity(program.expressions.len());
    let mut depths: Vec<u128> = Vec::with_capacity(program.expressions.len());
    for expression in &program.expressions {
        let (children, fanout): ([crate::ExprId; 2], usize) = match expression {
            crate::Expr::Binary { lhs, rhs, .. } => ([*lhs, *rhs], 2),
            crate::Expr::Not { value } => ([*value, 0], 1),
            _ => ([0, 0], 0),
        };
        let (mut size, mut depth) = (1u128, 0u128);
        for child in &children[..fanout] {
            let index = usize::from(*child);
            let (Some(child_size), Some(child_depth)) = (sizes.get(index), depths.get(index)) else {
                return Err(contract("expression-order"));
            };
            size = size.saturating_add(*child_size);
            depth = depth.max(*child_depth);
        }
        sizes.push(size);
        depths.push(depth + 1);
    }

// Conservative over the adapter: unsupported statements stop preparation early.
let (mut lets, mut occurrences, mut value_depth) = (0u128, 0u128, 0u128);
for statement in &action.statements {
    let (value, binder) = match statement {
        crate::Statement::Let { value, .. } => (*value, 1),
        crate::Statement::Emit { value, .. } => (*value, 0),
        _ => continue,
    };
    let index = usize::from(value);
    let (Some(size), Some(depth)) = (sizes.get(index), depths.get(index)) else {
        return Err(contract("statement-expression"));
    };
    lets += binder;
    occurrences = occurrences.saturating_add(binder).saturating_add(*size);
    value_depth = value_depth.max(*depth);
}
within(HostMeasure::ProjectionOccurrences, Some(occurrences),
    count(bounds.max_projection_occurrences))?;
// Let i sits at depth i; its deepest value node at i + depth(value).
let ast_nesting_bound = lets.saturating_add(value_depth);
within(HostMeasure::AstNesting, Some(ast_nesting_bound), count(bounds.max_ast_nesting))?;
let step_record_bound = within(HostMeasure::StepRecords, initial_fuel.checked_add(1),
    count(bounds.max_step_records))?;
let events = usize::try_from(step_record_bound).map_err(|_| contract("step-record-width"))?;
let arity = count(action.inputs.len()).max(count(arguments.len()));
let frame_bound = count(bounds.stack_limit).min(initial_fuel);
let environment_entry_bound = arity.saturating_add(lets);
let peak_slot_bound = within(HostMeasure::RetainedSlots,
    peak_slots(initial_fuel, frame_bound, environment_entry_bound, arity),
    bounds.max_retained_slots)?;

let mapped = prepare_scalar_action(program, action_index)
    .map_err(HostObservationRefusal::Projection)?;

fn within(measure: HostMeasure, required: Option<u128>, bound: u128)
    -> Result<u128, HostObservationRefusal>
{
    match required {
        Some(value) if value <= bound => Ok(value),
        required => Err(HostObservationRefusal::Exceeded { measure, required, bound }),
    }
}

fn scalar(ty: Type) -> bool {
    matches!(ty, Type::UInt | Type::Bool)
}

/// Snapshot units: initial, terminal, two per record, the live machine state
/// and one transient control/frame copy inside a step. Per snapshot: its
/// environment, a control holding at most a frame plus an environment, and
/// each frame holding at most one environment, arity values and arity
/// pending arguments. Lists, trees and match arms are unreachable here.
fn peak_slots(fuel: u128, frames: u128, entries: u128, arity: u128) -> Option<u128> {
    let per_unit = entries.checked_add(arity.checked_mul(2)?)?.checked_add(1)?;
    let per_snapshot = frames.checked_add(3)?.checked_mul(per_unit)?;
    fuel.checked_mul(2)?.checked_add(6)?.checked_mul(per_snapshot)

    let mapped = prepare_scalar_action(program, action_index)
        .map_err(HostObservationRefusal::Projection)?;
    if count(mapped.report.occurrences.len()) > occurrences {
        return Err(contract("occurrence-precount"));
    }
    let function = mapped.function;
    if function.parameters.len() != action.inputs.len()
        || !function.parameters.iter().all(|parameter| scalar(parameter.ty))
        || !scalar(function.return_type)
    {
        return Err(contract("generated-signature"));
    }
    // Each occurrence is exactly one fresh generated body node.
    let (nodes, observed_ast_nesting) = admitted_body(&function.body, mapped.report.occurrences.len())
        .map_err(contract)?;
    if nodes != mapped.report.occurrences.len() || count(observed_ast_nesting) > ast_nesting_bound {
        return Err(contract("generated-body-extent"));
    }
    let argument_types_match_inputs = arguments.len() == action.inputs.len()
        && arguments.iter().zip(&action.inputs).all(|(value, input)| matches!((value, input.ty),
            (Value::UInt(_), crate::Type::UInt) | (Value::Bool(_), crate::Type::Bool)));

    // The fixed diagnostic invocation of the returned real function.
    let entry = Arc::new(Expr::Call(function.name.clone(), arguments.iter()
        .map(|value| Arc::new(Expr::Literal(value.clone()))).collect()));
    let generated = Arc::new(Program { functions: vec![function], entry });
    let mut machine = Machine::new(generated.clone(), initial_fuel, bounds.stack_limit);
    let initial = machine.snapshot();
    let records = machine.run_steps(events);
    let terminal = machine.snapshot();
    if matches!(terminal.outcome, Outcome::Pending) {
        return Err(HostObservationRefusal::UnpublishedOutcome);
    }
    let terminal_has_next = machine.step().is_some();
    Ok(BoundedSourceObservation {
        report: mapped.report, program: generated, initial, records, terminal, terminal_has_next,
        extent: HostExtent { bounds, projected_occurrences: occurrences, ast_nesting_bound,
            observed_ast_nesting, step_record_bound, frame_bound, environment_entry_bound,
            peak_slot_bound, argument_types_match_inputs },
        qualification: QUALIFICATION,
    })
}

/// Explicit-stack walk admitting only the forms the scalar adapter emits.
/// Returns the node count and nesting, stopping once `node_limit` is passed.
fn admitted_body(body: &ExprRef, node_limit: usize) -> Result<(usize, usize), &'static str> {
    let mut pending = vec![(body, 1usize)];
    let (mut nodes, mut nesting) = (0usize, 0usize);
    while let Some((expr, depth)) = pending.pop() {
        nodes += 1;
        if nodes > node_limit {
            return Err("generated-node-count");
        }
        nesting = nesting.max(depth);
        match &**expr {
            Expr::Literal(Value::UInt(_) | Value::Bool(_)) | Expr::Var(_) => {}
            Expr::Let(_, value, body) => {
                pending.push((value, depth + 1));
                pending.push((body, depth + 1));
            }
            Expr::Binary(BinaryOp::Add | BinaryOp::Sub | BinaryOp::Mul | BinaryOp::Eq
                | BinaryOp::Lt, left, right) => {
                pending.push((left, depth + 1));
                pending.push((right, depth + 1));
            }
            Expr::Unary(UnaryOp::Not, value) => pending.push((value, depth + 1)),
            _ => return Err("generated-node-form"),
        }
    }
    Ok((nodes, nesting))
}

